// ScheddServer is the server API for Schedd service.
// All implementations must embed UnimplementedScheddServer
// for forward compatibility.
//
// Schedd is the gRPC service schedd exposes on its unix socket. Two RPCs for
// v1.0 — gatewayd-internal is the only caller. Multi-host (Gate-A) replaces the socket
// with mTLS; this ADR-018 surface is per-host.
type ScheddServer interface {
	// Wake ensures an instance for the app is running and returns the address
	// the gateway should proxy to. Blocks for the duration of admission +
	// (restore | cold boot) + readiness. Idempotent: a request for an app that
	// already has a running instance returns that instance's address without a
	// new boot. Admission denial (RAM ceiling / plan concurrency / vCPU slots)
	// returns a ResourceExhausted status carrying the RFC 7807 problem so the
	// gateway can serve a 503 (spec §4.3).
	Wake(context.Context, *WakeRequest) (*WakeResponse, error)
	// AdmitInstance attempts to admit ONE additional instance for the app
	// (issue #168). Unlike Wake, this RPC skips the Phase-1 fast-path
	// shortcut so a gateway can demand a new instance even when others
	// are already RUNNING. The gateway uses it to fan-out across
	// max_concurrency without hitting the WakeGate's single-flight
	// coalescing.
	//
	// Three outcomes:
	//
	//   - admitted: a new RUNNING instance was created. instance_id,
	//     node_id, method, wake_id are populated.
	//   - at_capacity: the app is already at effective max_concurrency.
	//     at_capacity=true; instance_id/node_id/wake_id are unset. The
	//     gateway treats this as a benign no-op when it already has ≥1
	//     cached target.
	//   - failure: RAM headroom / chooser / store errors. ResourceExhausted
	//     or Internal status carrying the RFC 7807 problem in `problem`.
	//
	// Stability: the wire is additive — adding at_capacity and a
	// separate request/response message is the only contract change.
	// Existing Wake callers are unaffected.
	AdmitInstance(context.Context, *AdmitInstanceRequest) (*AdmitInstanceResponse, error)
	// ReportActivity records per-instance last_request_at touches the gateway
	// batches (spec §4.1 flushes every 15 s). schedd persists them because
	// schedd is the ONLY writer to the `instances` table (CLAUDE.md ownership);
	// the gateway keeps the batch in memory between flushes (ADR-018).
	ReportActivity(context.Context, *ReportActivityRequest) (*ReportActivityResponse, error)
	// VMMD reports readiness observed on an instance-bound guest channel.
	// Schedd owns the persisted timestamp and serializes it against park/destroy.
	ReportFrameworkReady(context.Context, *FrameworkReadyReport) (*FrameworkReadyAck, error)
	// ParkInstance forces an instance to its parked state. Added in M7 so
	// meterd's Free-tier hard-stop can park every live instance on a
	// suspended account (spec §4.7). Reason is for audit logs ("quota_
	// exceeded_free" etc). Returns Ok on success; ResourceExhausted / NotFound
	// for the obvious error paths.
	ParkInstance(context.Context, *ParkInstanceRequest) (*ParkInstanceResponse, error)
	// ForceColdBootNextWake asks schedd to mark the deployment's
	// latest warm + init snapshots stale so the next customer Wake
	// cold-boots from rootfs per ADR-005. Operator-side recovery
	// primitive (P2b of the operator-side observability mega-PR):
	// when a wedged instance is reported and the snapshot is
	// suspected to be the carrier, the on-call engineer forces a
	// one-shot cold-boot instead of parking the live instance.
	// Returns the snap IDs that were marked stale (empty when the
	// deployment has no snapshots — durable no-op). NotFound when
	// the deployment does not exist. Idempotent.
	ForceColdBootNextWake(context.Context, *ForceColdBootNextWakeRequest) (*ForceColdBootNextWakeResponse, error)
	// ForceRestartInstance (P2d follow-on) is the operator-initiated
	// kill-instance + cold-boot-on-next-wake primitive. Distinct from
	// ForceColdBootNextWake (snapshot flip only, no destroy) and
	// ParkInstance (park, no snapshot flip). Engine.ForceRestart:
	//
	//   - if the locked re-read observes a non-RUNNING state,
	//     returns ok=false with error_msg="state: instance not in
	//     running state" (race-loser posture; the customer-driven
	//     action won the lock — desired end-state achieved, no
	//     audit-row-repaint needed).
	//   - on success, fires the destroy (RUNNING → STOPPED via
	//     transitionWithKind with kind "force_restart"), flips
	//     warm + init snapshots stale, and returns ok=true with the
	//     snap IDs marked stale populated.
	//
	// Codes: NotFound when the instance_id doesn't exist; FailedPrecondition
	// when the locked re-read observed a non-RUNNING state AND the
	// error path is mapped to a gRPC status (the server returns
	// ok=false on the wire rather than a status error so the
	// gregalectl CLI can render the cause verbatim). Internal on
	// unexpected errors (destroy failure surfaces as ok=true +
	// snap_ids_marked_stale populated + error_msg populated so
	// the operator learns the partial-success shape).
	//
	// Additive per ADR-016.
	ForceRestartInstance(context.Context, *ForceRestartInstanceRequest) (*ForceRestartInstanceResponse, error)
	// ListInstanceStats returns the per-instance CPU-µs snapshot the
	// schedd's instancestats.Poller maintains (issue #279 / PR-B).
	// meterdsamp the per-minute CPU delta from this snapshot and
	// writes it to usage_minutes.cpu_usec. Returned rows are the
	// same shape the wire rollup observes (pkg/wire.InstanceStatRow
	// is the typed mirror; the proto is wire-stable so adding a
	// field is additive).
	//
	// CPUUsageUsec is the cumulative host cgroup CPU-µs consumed
	// since the cgroup was created. On a cgroup recreation (jailer
	// restart, manual rmdir) the counter resets to a smaller
	// number — callers must treat the reset as a fresh baseline.
	// CPUValid mirrors instancestats.Validity: 0 = Valid, 1 =
	// Unknown (the vmmd cpustats.Cache has no baseline yet, or a
	// post-regression row). Callers MUST skip rows where CPUValid
	// != 0; otherwise the baseline becomes "stuck" on the pre-
	// regression counter and the per-minute delta is meaningless.
	//
	// Additive: the RPC is the only piece of new wire metadata
	// needed for PR-B. The vmmd Stats RPC already carries the per-
	// instance CPU numbers; this RPC is the schedd-side cache of
	// those numbers, refreshed by the poller every 200 ms.
	ListInstanceStats(context.Context, *ListInstanceStatsRequest) (*ListInstanceStatsResponse, error)
	// StreamAppLogs (issue #254 / Move 4) fans out an app's per-instance
	// ring buffers back to the caller as a server-streaming response.
	// schedd is the policy owner and the only component allowed to talk
	// to vmmd directly (CLAUDE.md ownership); apid dials this RPC and
	// multiplexes the per-instance frames into a single SSE response.
	//
	// Two phases mirror vmmd's Logs RPC:
	//
	//  1. Initial page — every line with Seq > since_seq, emitted in
	//     per-instance order (then instance order), so a reconnect
	//     carries the same frame sequence the client last saw.
	//  2. Live tail — schedd subscribes to each live instance's
	//     vmmd Logs stream and emits new lines as they arrive. On
	//     instance death (park/snapshot) the per-instance stream ends
	//     and the next frame is a global "end" event.
	//
	// Wire error mapping:
	//
	//   - codes.NotFound when the app has zero live instances — apid
	//     maps this to its 404 "the app is parked; wake it first"
	//   - codes.Unavailable when the vmmd is unreachable for SOME
	//     instances — apid emits a `degraded` event and keeps the
	//     surviving streams open
	//   - codes.OK + nil on clean shutdown
	//
	// Additive per ADR-016: the field tags on existing messages are
	// untouched; new RPC + new messages append at the end.
	StreamAppLogs(*StreamAppLogsRequest, grpc.ServerStreamingServer[StreamAppLogsResponse]) error
	// StreamWarmHints (ADR-025 axis 4) is the sticky-warm affinity push.
	// schedd is the only writer to pkg/sched.WarmAffinity; every successful
	// admit stamps (app_id → node_id) and we forward the stamp as an event
	// so gatewayd-internal's picker (PGBackend.WarmHintFunc) can bias traffic to the
	// warm node on multi-box fleets.
	//
	// Semantics:
	//   - Server-streaming; gatewayd-internal opens one stream at startup and keeps
	//     it open for the lifetime of the connection.
	//   - "Tail from now": no replay cursor, no snapshot on connect. ADR-005
	//     guarantees an empty hint falls through to least-loaded, so a
	//     gatewayd-internal that reconnects with no hint still routes correctly.
	//   - Events are emitted only on state change (RecordWake actually
	//     changed app_id → node_id); a periodic RecordWake to the same node
	//     is a no-op event-source-wise. The producer filters at emit time.
	//
	// Wire error mapping:
	//   - codes.OK + nil on clean shutdown (caller cancels)
	//   - codes.Canceled when the gateway cancels
	//   - codes.Unavailable for any unexpected drain failure
	//
	// Additive per ADR-016: new RPC + new messages append at the end;
	// existing field tags are untouched.
	StreamWarmHints(*StreamWarmHintsRequest, grpc.ServerStreamingServer[StreamWarmHintsResponse]) error
	// ReportCapacity (ADR-025 axis 5) is the vmmd→schedd live-capacity
	// push. vmmd is the gRPC client and opens one stream per daemon at
	// startup, sending a CapacityReport at ~1 s cadence (constant
	// cmd/vmmd.CapacityInterval). schedd updates a per-node in-memory
	// table that the placement chooser reads before falling back to the
	// store's stale-sum aggregate.
	//
	// Trust model: the chooser reads capacity as one input to
	// ChoosePlacement, never as the only input. The per-node
	// AdmissionCeilingMB check inside ChoosePlacement
	// (pkg/sched/placement.go:104-107) and the per-node ledger floor
	// (pkg/sched/engine.go::applyLiveCapacityMB, PR-2) are the
	// load-bearing enforcement; capacity reports inform, never gate.
	// A stale-low or hostile vmmd cannot shrink the live accounting
	// below the ledger's per-node ResidentRAM and force schedd to
	// over-admit (§6.2-2 invariant).
	//
	// Semantics:
	//   - Client-streaming; vmmd is the producer.
	//   - "Tail from now": the consumer accepts reports as they arrive;
	//     a slow vmmd never back-pressures because reports are best-effort.
	//   - An empty capacity table (no reports within
	//     CapacityFreshness = 5 s) falls back to
	//     store.ComputeNodeUsedMB — the legacy single-box behaviour.
	//     Single-box installs without a publisher configured see
	//     identical behaviour to pre-axis-5.
	//
	// Wire error mapping:
	//   - codes.OK + nil on clean shutdown (vmmd cancels after CloseAndRecv
	//     completes)
	//   - codes.Canceled when vmmd cancels mid-stream
	//   - codes.Unavailable for any unexpected drain failure
	//   - codes.InvalidArgument if a report's node_id is empty (a
	//     programming bug in vmmd; the handler must NOT silently drop).
	//
	// Additive per ADR-016: new RPC + new messages append at the end;
	// existing field tags are untouched.
	ReportCapacity(grpc.ClientStreamingServer[CapacityReport, ReportCapacityAck]) error
	// ReportLivenessFailed (issue #554 / ADR-078) is the vmmd-side
	// push of a per-instance liveness-probe N-consecutive-failure
	// (or timeout / conn-refused) detection. vmmd's poll goroutine
	// dials this RPC whenever the consecutive-failure counter
	// reaches the per-plan N (default 3); schedd's
	// Engine.DestroyForLivenessFailure consumes the report,
	// eagerly marks the deployment's snapshot stale (ADR-005),
	// resets the idle timer, and parks the parent app after 3
	// restarts in 300 s. Idempotent on the wire: re-reporting the
	// same instance id is a no-op on the schedd side because the
	// state-machine guards against destroying a non-RUNNING
	// instance.
	//
	// Reason is the closed set {timeout, conn_refused, conn_err,
	// non_200, n_consecutive} — the same closed set the
	// vmmd_guest_liveness_probe_seconds histogram emits. The
	// schedd Engine stamps the reason into the audit row's
	// data JSON.
	//
	// Additive per ADR-016: new RPC + new messages append at the
	// end; existing field tags are untouched.
	ReportLivenessFailed(context.Context, *LivenessFailedReport) (*LivenessFailedAck, error)
	// EnsureWake (ADR-098) is the single-flight-friendly wake entry
	// point. Unlike Wake, it serialises the wake hot path through the
	// engine's per-app wake coordinator (pkg/sched/wake_coord.go) so a
	// concurrent gateway request + cron tick + floor trigger + scaleup
	// trigger + targets trigger all coalesce into one boot. The first
	// caller becomes the leader; followers block on the leader's
	// outcome and inherit the same (RunningInstance, error) they would
	// have seen had they called Engine.Wake / Engine.AdmitInstance
	// directly.
	//
	// Three outcomes:
	//
	//   - already-running: a Row with state RUNNING already exists for
	//     the app. The leader and all followers see the same
	//     EnsureWakeResponse. instance_id / node_id / wake_id are
	//     populated. No vmm RPC fires.
	//   - leader-boot: the leader schedules a new wake via the existing
	//     engine path. Followers wait on the leader's outcome. The
	//     leader's response carries the freshly-minted instance_id /
	//     node_id / wake_id once vmmd returns RUNNING.
	//   - failure: ledger / chooser / store error. ResourceExhausted or
	//     Internal status carrying the RFC 7807 problem in `problem`.
	//     Followers see the same error. A leader that fails to commit
	//     Phase 4 returns FailedPrecondition so the gateway can
	//     distinguish "deliberately reduced" from "VM came up but lost
	//     the race" - the former is retryable, the latter is not.
	//
	// Stability: the wire is additive per ADR-016. Wake / AdmitInstance
	// are unchanged; pre-PR-95 callers observe identical behaviour.
	// Empty WakeMethod in the response means the engine returned the
	// existing-instance fast path (no new boot happened).
	EnsureWake(context.Context, *EnsureWakeRequest) (*EnsureWakeResponse, error)
	// ReportWorkloadOOM (Cluster C, ADR-121) is the vmmd-side push
	// of a per-instance runtime OOM-kill detection on the customer's
	// workload cgroup. vmmd's framework_ready_recv dispatcher
	// forwards the guest-init's cgroup.events "oom_kill" signal as
	// soon as it arrives on AF_VSOCK port 1027 (type byte 0x05);
	// schedd's Engine.DestroyForWorkloadOOMFailure consumes the
	// report, eagerly marks the deployment's snapshot stale (ADR-005),
	// stamps CodeAppRuntimeOOM on the deployment row with the
	// templated whycopy Observed payload (peak MB + plan cap), and
	// transitions the instance RUNNING → STOPPED with kind
	// "workload_oom_failed".
	//
	// Distinct from ReportLivenessFailed: the workload is dead
	// before the kernel can report liveness probe failures (the
	// listener goroutine inside the microVM is the only path that
	// sees the workload OOM). peak_mb / plan_mb are the observed
	// payload; the engine uses them to populate the whycopy
	// Observed closure.
	//
	// Idempotent on the wire: re-reporting the same instance id is
	// a no-op on the schedd side because the state-machine guard
	// refuses to destroy a non-RUNNING instance.
	//
	// Additive per ADR-016: new RPC + new messages append at the
	// end; existing field tags are untouched.
	ReportWorkloadOOM(context.Context, *ReportWorkloadOOMRequest) (*ReportWorkloadOOMAck, error)
	mustEmbedUnimplementedScheddServer()
}

